partial class Studio {
 public void TestVersion24(){SetDocument(new Document("A4",100),null);mode.SelectedItem="HSV";colourEntry.Text="120, 100, 100";ApplyColourEntry();if(canvas.Ink.ToArgb()!=Color.Lime.ToArgb())throw new Exception("HSV typed colour");var hue=(NumericUpDown)channels.Controls[0].Controls[1];hue.Value=240;if(canvas.Ink.ToArgb()!=Color.Blue.ToArgb())throw new Exception("HSV channel editing");SetNeutral("Black");if(canvas.Ink.ToArgb()!=Color.Black.ToArgb())throw new Exception("Black shortcut");SetNeutral("Grey");value.Value=25;if(canvas.Ink.R!=canvas.Ink.G||canvas.Ink.G!=canvas.Ink.B||Math.Abs(canvas.Ink.R-64)>1)throw new Exception("Grey brightness adjustment");SetNeutral("White");if(canvas.Ink.ToArgb()!=Color.White.ToArgb())throw new Exception("White shortcut");if(selectionMode.Parent!=null||selectionButtons["Box selection"].Parent!=darkMode.Parent)throw new Exception("Top selection buttons");selectionButtons["Box selection"].PerformClick();if(canvas.SelectionMode!="Box selection")throw new Exception("Selection button action");SelectTool("Pen");AddTypedLayer(true);if(!selectionButtons["Box selection"].Enabled||vectorMode.Parent!=null||vectorButtons.Values.Any(b=>b.Image==null))throw new Exception("Vector buttons/icons");vectorButtons["Curvature pen"].PerformClick();canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.TestDrag(new Point(100,100),new Point(100,100));canvas.TestDrag(new Point(200,200),new Point(200,200));canvas.TestDrag(new Point(300,100),new Point(300,100));canvas.FinishVector();vectorPicker.PerformClick();canvas.TestDrag(new Point(200,200),new Point(200,200));var shape=canvas.SelectedVector;int count=shape.Points.Count;canvas.EditCurvePoint(true);if(shape.Points.Count!=count||addCurvePoint.Enabled)throw new Exception("One selected point must not add");canvas.SelectVectorPoint(0,false);canvas.SelectVectorPoint(2,true);if(!addCurvePoint.Enabled)throw new Exception("Two selected points enable add");addCurvePoint.PerformClick();if(shape.Points.Count!=count+1||shape.Points[1]!=new PointF(200,100)||addCurvePoint.Enabled)throw new Exception("Exact midpoint insertion");Travel(undo,redo);if(canvas.Doc.Selected.Vectors[0].Points.Count!=count)throw new Exception("Midpoint undo");canvas.TestDrag(new Point(200,200),new Point(200,200));canvas.SelectVectorPoint(0,false);canvas.SelectVectorPoint(1,true);canvas.SelectVectorPoint(2,true);canvas.EditCurvePoint(true);if(canvas.Doc.Selected.Vectors[0].Points.Count!=count||addCurvePoint.Enabled)throw new Exception("Three selected points must not add");dirty=false;}
 readonly Dictionary<string,Button> selectionButtons=new Dictionary<string,Button>(),vectorButtons=new Dictionary<string,Button>();Button addCurvePoint,removeCurvePoint;
 Button savedColoursButton;void AddNeutralColours(Panel colour){foreach(Control c in colour.Controls)if(c.Top>=192)c.Top+=38;colour.Height+=38;int index=0;foreach(var name in new[]{"Black","Grey","White"}){string label=name;var b=Theme.Button(label.ToUpperInvariant(),delegate{SetNeutral(label);});b.SetBounds(index++*60,192,58,28);colour.Controls.Add(b);}var palette=savedColoursButton=Theme.Button("Colours",delegate{ShowColourPalette();});palette.SetBounds(180,192,56,28);colour.Controls.Add(palette);}
 void SetNeutral(string name){canvas.Ink=name=="Black"?Color.Black:name=="White"?Color.White:Color.FromArgb(128,128,128);wheel.SetColor(canvas.Ink);SyncColour();canvas.ApplyVectorColour();}
 void AddTopSelectionButtons(){var top=(FlowLayoutPanel)darkMode.Parent;var gap=new Panel{Width=28,Height=34,Margin=Padding.Empty};top.Controls.Add(gap);foreach(string name in new[]{"Ellipse selection","Box selection","Polygon selection","Lasso selection"}){string selected=name;var b=Theme.Button(name.Replace(" selection"," select"),delegate{if(canvas.Doc!=null&&canvas.Doc.Selected.IsVector){vectorMode.SelectedItem="Select/edit";canvas.SetSelectionMode("Draw");if(selected=="Box selection")canvas.StartVectorBox();else canvas.SetSelectionMode(selected);}else selectionMode.SelectedItem=selected;UpdateSelectionButtons();canvas.Focus();});b.Width=name.StartsWith("Ellipse")||name.StartsWith("Polygon")?126:110;b.TextAlign=ContentAlignment.MiddleCenter;selectionButtons[name]=b;top.Controls.Add(b);}var deselect=Theme.Button("Deselect",delegate{if(canvas.Doc!=null&&canvas.Doc.Selected.IsVector)canvas.CancelVector();else canvas.ClearSelection();selectionMode.SelectedItem="Draw";canvas.SetSelectionMode("Draw");UpdateSelectionButtons();canvas.Focus();});deselect.TextAlign=ContentAlignment.MiddleCenter;selectionButtons["Deselect"]=deselect;top.Controls.Add(deselect);}
 void UpdateSelectionButtons(){bool enabled=canvas.Doc!=null&&!canvas.Doc.Selected.IsVector;foreach(var pair in selectionButtons){pair.Value.Enabled=canvas.Doc!=null&&(enabled||canvas.Doc.Selected.IsVector);pair.Value.BackColor=(pair.Key==canvas.SelectionMode||pair.Key=="Box selection"&&canvas.Doc!=null&&canvas.Doc.Selected.IsVector&&canvas.VectorBoxMode)?Theme.Accent:Theme.Panel;pair.Value.ForeColor=Theme.Text;}}
 static Bitmap VectorIcon(string name,int size=26){var b=new Bitmap(size,size);using(var g=Graphics.FromImage(b))using(var pen=new Pen(Color.Teal,2)){g.ScaleTransform(size/26f,size/26f);g.SmoothingMode=SmoothingMode.AntiAlias;if(name=="Line"){g.DrawLine(pen,4,21,22,5);g.FillRectangle(Brushes.Teal,2,19,4,4);g.FillRectangle(Brushes.Teal,20,3,4,4);}else if(name=="Rectangle")g.DrawRectangle(pen,3,5,20,16);else if(name=="Ellipse")g.DrawEllipse(pen,3,6,20,14);else if(name=="Freehand"){g.DrawCurve(pen,new[]{new PointF(3,20),new PointF(7,8),new PointF(15,19),new PointF(22,4)});g.DrawLine(pen,17,4,23,2);}else if(name=="Polyline"){g.DrawLines(pen,new[]{new Point(3,21),new Point(8,5),new Point(17,21),new Point(23,4)});}else if(name=="Vector pen"){g.DrawBezier(pen,3,22,3,2,23,24,23,4);g.DrawLine(Pens.Gray,3,22,3,2);g.DrawLine(Pens.Gray,23,4,23,24);g.FillRectangle(Brushes.Teal,1,20,4,4);g.FillRectangle(Brushes.Teal,21,2,4,4);}else if(name=="Curvature pen"){g.DrawCurve(pen,new[]{new PointF(3,21),new PointF(9,5),new PointF(18,19),new PointF(23,4)});foreach(var p in new[]{new Point(3,21),new Point(9,5),new Point(18,19),new Point(23,4)})g.FillRectangle(Brushes.Teal,p.X-2,p.Y-2,4,4);}else{g.DrawPolygon(pen,new[]{new Point(13,2),new Point(24,10),new Point(20,23),new Point(6,23),new Point(2,10)});}}return b;}
 void AddVectorButtons(FlowLayoutPanel tools){foreach(string name in new[]{"Freehand","Line","Polyline","Vector pen","Curvature pen","Rectangle","Ellipse","Polygon"}){string tool=name;var b=Theme.Button(name,delegate{vectorMode.SelectedItem=tool;canvas.Focus();});b.Width=170;b.Height=34;b.Image=VectorIcon(name);b.ImageAlign=ContentAlignment.MiddleLeft;b.TextAlign=ContentAlignment.MiddleRight;vectorButtons[name]=b;tools.Controls.Add(b);}AddTextTool(tools);UpdateVectorButtons();}
 void UpdateVectorButtons(){UpdateBooleanControls();SyncRadiusControls();if(vectorPicker!=null){vectorPicker.BackColor=canvas.VectorMode=="Select/edit"?Theme.Accent:Theme.Panel;vectorPicker.ForeColor=Theme.Text;}polygonSides.Enabled=canvas.VectorMode=="Polygon";if(polygonSidesSlider!=null)polygonSidesSlider.Enabled=polygonSides.Enabled;foreach(var label in vectorControls.OfType<Label>().Where(l=>l.Text.StartsWith("POLYGON SIDES")))label.Enabled=polygonSides.Enabled;if(pointSpacingLabel!=null){bool enabled=canvas.VectorMode=="Freehand";pointSpacing.Enabled=enabled;pointSpacingLabel.Enabled=enabled;}foreach(var pair in vectorButtons){pair.Value.BackColor=pair.Key==canvas.VectorMode?Theme.Accent:Theme.Panel;pair.Value.ForeColor=Theme.Text;}}
 void UpdatePointButtons(){UpdateBooleanControls();SyncRadiusControls();if(simplifyPaths!=null)simplifyPaths.Enabled=canvas.CanSimplifySelection;if(addCurvePoint!=null)addCurvePoint.Enabled=canvas.CanAddCurvePoint;if(removeCurvePoint!=null)removeCurvePoint.Enabled=canvas.CanRemoveCurvePoint;}
}
partial class Canvas {
 readonly HashSet<int> selectedPoints=new HashSet<int>();public Action PointSelectionChanged;
 public bool CanAddCurvePoint {get{return selectedVector!=null&&selectedVector.Kind!="Compound"&&selectedVector.Kind!="Text"&&selectedPaths.Count==1&&selectedPoints.Count==2&&selectedPoints.All(i=>i>=0&&i<selectedVector.Grips().Length);}}
 public bool CanRemoveCurvePoint {get{return selectedVector!=null&&selectedVector.Kind!="Compound"&&selectedVector.Kind!="Text"&&selectedPaths.Count==1&&selectedPoints.Count>0&&selectedVector.Grips().Length-selectedPoints.Count>=MinimumShapePoints(selectedVector);}}
 void NotifyPointSelection(){if(PointSelectionChanged!=null)PointSelectionChanged();}
 public void SelectVectorPoint(int index,bool extend){if(selectedVector==null)return;if(!extend)selectedPoints.Clear();selectedPoints.Add(index);NotifyPointSelection();Invalidate();}
}
}
